<script setup>
import {auth} from './adminApi.js'
import {ref,computed,onMounted} from 'vue'
import {analyticsZones,dayAt,addDays} from '../../../shared/analytics.js'
const props=defineProps({apiWrite:Function})
const report=ref(null),loading=ref(false),error=ref(''),saving=ref(false),showSettings=ref(false),metric=ref('visitors'),preset=ref(7)
const settings=ref({enabled:true,exclude_admin:true,timezone:'Asia/Novosibirsk'}),from=ref(''),to=ref('')
const today=computed(()=>dayAt(new Date(),settings.value.timezone)),minDay=computed(()=>addDays(today.value,-89))
const counts={visitors:'Посетители',sessions:'Сессии',pageviews:'Просмотры'}
const devices={desktop:'Компьютер',mobile:'Телефон',tablet:'Планшет'}
const money=cents=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',minimumFractionDigits:0,maximumFractionDigits:2}).format(cents/100)
const number=value=>new Intl.NumberFormat('ru-RU').format(value||0)
const percentage=(a,b)=>b?new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(a/b*100)+'%':'—'
const max=computed(()=>Math.max(1,...(report.value?.days||[]).map(x=>x[metric.value])))
const points=computed(()=>(report.value?.days||[]).map((row,i,rows)=>({x:rows.length===1?450:20+i*860/(rows.length-1),y:210-row[metric.value]/max.value*185,row})))
const line=computed(()=>points.value.map(p=>p.x+','+p.y).join(' '))
const area=computed(()=>points.value.length?`${points.value[0].x},210 ${line.value} ${points.value.at(-1).x},210`:'')
let generation=0
async function load(){const token=++generation;loading.value=true;error.value='';try{const data=await props.apiWrite('/api/admin/analytics?'+new URLSearchParams({from:from.value,to:to.value}),'GET');if(token===generation)report.value=data}catch(e){if(token===generation)error.value=e.message}finally{if(token===generation)loading.value=false}}
function range(days){preset.value=days;to.value=today.value;from.value=addDays(to.value,1-days);load()}
async function saveSettings(){saving.value=true;error.value='';try{settings.value=await props.apiWrite('/api/admin/analytics/settings','PUT',{...settings.value});range(preset.value||7)}catch(e){error.value=e.message}finally{saving.value=false}}
function exportCsv(){
 const data=report.value;if(!data)return
 const rows=[['Аналитика NOVA',data.range.from,data.range.to,data.range.timezone],['Посетители','Сессии','Просмотры','Заказы','Выполненные (коп.)'],[data.summary.visitors,data.summary.sessions,data.summary.pageviews,data.commerce.orders,data.commerce.completed_cents],[],['Дата','Посетители','Сессии','Просмотры'],...data.days.map(x=>[x.day,x.visitors,x.sessions,x.pageviews]),[],['Страница','Просмотры','Сессии'],...data.pages.map(x=>[x.path,x.pageviews,x.sessions]),[],['Источник','Сессии'],...data.sources.map(x=>[x.name||'Прямые переходы',x.sessions])]
 const csv='\uFEFF'+rows.map(row=>row.map(value=>{let text=String(value??'');if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'}).join(';')).join('\r\n')
 const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='nova-analytics-'+data.range.from+'-'+data.range.to+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)
}
onMounted(async()=>{try{settings.value=await props.apiWrite('/api/admin/analytics/settings','GET');range(7)}catch(e){error.value=e.message}})
</script>
<template>
<div class="analytics-workspace">
 <div class="page-title"><div><span class="eyebrow">СТАТИСТИКА САЙТА</span><h1>Аналитика</h1><p>Посещения, источники переходов и результаты магазина.</p></div><div class="analytics-buttons"><button class="row-btn" :disabled="!report||loading" @click="exportCsv">Скачать CSV</button><button class="row-btn" v-if="auth.user.role!=='manager'" @click="showSettings=!showSettings">Настройки сбора</button></div></div>
 <form v-if="showSettings" class="panel analytics-settings" @submit.prevent="saveSettings"><h2>Сбор статистики</h2><fieldset :disabled="saving"><label class="analytics-check"><input v-model="settings.enabled" type="checkbox"> Собирать посещения сайта</label><label class="analytics-check"><input v-model="settings.exclude_admin" type="checkbox"> Исключать посещения вошедшего администратора</label><label>Часовой пояс отчётов<select v-model="settings.timezone" aria-label="Часовой пояс"><option v-for="zone in analyticsZones" :key="zone" :value="zone">{{zone}}</option></select></label><p>История посещений хранится 90 дней. Если браузер запрещает отслеживание, посещения не учитываются. После включения сбора обновите открытую страницу сайта.</p><button class="primary-btn">{{saving?'Сохранение…':'Сохранить настройки'}}</button></fieldset></form>
 <div class="panel analytics-period"><div class="analytics-presets"><button v-for="(label,days) in {1:'Сегодня',7:'7 дней',30:'30 дней'}" :key="days" :class="{active:preset===Number(days)}" @click="range(Number(days))">{{label}}</button></div><form @submit.prevent="preset=0;load()"><label>С<input v-model="from" type="date" :min="minDay" :max="to||today" required aria-label="Начало периода"></label><label>По<input v-model="to" type="date" :min="from||minDay" :max="today" required aria-label="Конец периода"></label><button class="primary-btn" :disabled="loading">{{loading?'Загрузка…':'Показать'}}</button></form><small>{{report?.range.timezone||settings.timezone}}</small></div>
 <p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="report&&!report.settings.enabled" class="analytics-notice">Сбор посещений выключен. Ранее накопленные данные и показатели заказов доступны в отчёте.</p>
 <p v-if="loading&&!report" class="empty" role="status">Загрузка аналитики…</p>
 <template v-if="report"><div class="stats-grid analytics-stats"><div class="stat-card"><span>Посетители</span><strong>{{number(report.summary.visitors)}}</strong><small>Браузеры за выбранный период</small></div><div class="stat-card"><span>Сессии</span><strong>{{number(report.summary.sessions)}}</strong><small>30 минут без событий — новая сессия</small></div><div class="stat-card"><span>Просмотры</span><strong>{{number(report.summary.pageviews)}}</strong><small>Открытия публичных страниц</small></div><div class="stat-card"><span>Конверсия в заказ</span><strong>{{percentage(report.actions.ordered,report.actions.sessions)}}</strong><small>Сессии с неотменённым заказом</small></div></div>
 <div class="panel analytics-chart"><div class="panel-heading"><div><h2>Посещаемость по дням</h2><p>{{report.range.from}} — {{report.range.to}}</p></div><select v-model="metric" aria-label="Показатель графика"><option v-for="(label,key) in counts" :key="key" :value="key">{{label}}</option></select></div><div class="analytics-plot"><div class="analytics-scale"><span>{{number(max)}}</span><span>0</span></div><svg viewBox="0 0 900 230" preserveAspectRatio="none" role="img" :aria-label="counts[metric]+' по дням'"><line v-for="y in [25,71,117,164,210]" :key="y" x1="20" x2="880" :y1="y" :y2="y" stroke="#e3ece7"/><polygon :points="area" fill="#e3f2e9"/><polyline :points="line" fill="none" stroke="#287253" stroke-width="3" vector-effect="non-scaling-stroke"/><circle v-for="p in points" :key="p.row.day" :cx="p.x" :cy="p.y" r="4" fill="#287253"><title>{{p.row.day}}: {{p.row[metric]}}</title></circle></svg></div><div class="analytics-dates"><span>{{report.range.from}}</span><span>{{report.range.to}}</span></div><p v-if="!report.summary.pageviews" class="analytics-zero">Посещений пока нет. Статистика начнёт появляться после открытия сайта посетителями. Прошлые посещения восстановить нельзя.</p><details><summary>Данные по дням</summary><div class="table-scroll"><table><thead><tr><th>Дата</th><th>Посетители</th><th>Сессии</th><th>Просмотры</th></tr></thead><tbody><tr v-for="row in report.days" :key="row.day"><td>{{row.day}}</td><td>{{number(row.visitors)}}</td><td>{{number(row.sessions)}}</td><td>{{number(row.pageviews)}}</td></tr></tbody></table></div></details></div>
 <div class="analytics-grid"><div class="panel"><div class="panel-heading"><h2>Популярные страницы</h2><small>До 30 страниц</small></div><div class="table-scroll"><table><thead><tr><th>Страница</th><th>Просмотры</th><th>Сессии</th></tr></thead><tbody><tr v-for="row in report.pages" :key="row.path"><td>{{row.path}}</td><td>{{number(row.pageviews)}}</td><td>{{number(row.sessions)}}</td></tr></tbody></table><p v-if="!report.pages.length" class="empty">Данных пока нет.</p></div></div><div class="panel"><div class="panel-heading"><h2>Источники переходов</h2><small>Первый переход сессии</small></div><div class="analytics-ranking"><div v-for="row in report.sources" :key="row.name"><div><span>{{row.name||'Прямые переходы / источник не передан'}}</span><strong>{{number(row.sessions)}}</strong></div><meter :value="row.sessions" :max="Math.max(1,report.summary.sessions)"></meter></div><p v-if="!report.sources.length" class="empty">Данных пока нет.</p></div></div></div>
 <div class="analytics-grid"><div v-for="(group,title) in {Устройства:report.devices,Браузеры:report.browsers}" :key="title" class="panel"><div class="panel-heading"><h2>{{title}}</h2><small>Сессии</small></div><div class="analytics-ranking"><div v-for="row in group" :key="row.name"><div><span>{{devices[row.name]||row.name}}</span><strong>{{number(row.sessions)}} · {{percentage(row.sessions,report.summary.sessions)}}</strong></div><meter :value="row.sessions" :max="Math.max(1,report.summary.sessions)"></meter></div><p v-if="!group.length" class="empty">Данных пока нет.</p></div></div></div>
 <div class="panel analytics-actions"><div class="panel-heading"><div><h2>От посещения к заказу</h2><p>Количество сессий с каждым действием за период. Повторные нажатия в одной сессии считаются один раз.</p></div></div><div class="analytics-steps"><div v-for="(label,key) in {sessions:'Посетили сайт',cart:'Добавили в корзину',checkout:'Начали оформление',ordered:'Оформили заказ'}" :key="key"><span>{{label}}</span><strong>{{number(report.actions[key])}}</strong><small>{{percentage(report.actions[key],report.actions.sessions)}} от сессий</small></div></div><p class="analytics-footnote">Шаги показывают наличие события, а не обязательную последовательность. Заказ связывается с сессией только при работающем сборщике. Отменённые заказы исключены из конверсии.</p></div>
 <div class="stats-grid analytics-stats"><div class="stat-card"><span>Заказы периода</span><strong>{{number(report.commerce.orders)}}</strong><small>Включая отменённые: {{report.commerce.cancelled}}</small></div><div class="stat-card"><span>Выполнено из заказов периода</span><strong>{{number(report.commerce.completed)}}</strong><small>Текущий статус заказа</small></div><div class="stat-card"><span>Сумма выполненных заказов</span><strong class="analytics-money">{{money(report.commerce.completed_cents)}}</strong><small>Товары без стоимости доставки</small></div><div class="stat-card"><span>Средний заказ</span><strong class="analytics-money">{{money(report.commerce.average_cents)}}</strong><small>Все статусы, кроме отменённых</small></div></div>
 <p class="analytics-footnote">Заказы отбираются по дате оформления и текущему статусу. Сумма выполненных заказов не подтверждает получение оплаты. Посетители считаются приблизительно по браузерам: один человек может пользоваться несколькими устройствами. Данные заказов доступны и при выключенном сборе посещений.</p>
 </template>
</div>
</template>
<style scoped>
.analytics-workspace{min-width:0}.analytics-buttons,.analytics-presets{display:flex;gap:8px;flex-wrap:wrap}.analytics-buttons .row-btn{margin:0}.analytics-period{padding:20px;display:flex;align-items:end;gap:18px;flex-wrap:wrap;margin-bottom:24px}.analytics-presets button{padding:11px;border:1px solid #dbe6df;border-radius:7px;background:white}.analytics-presets button.active{background:#287253;color:#fff}.analytics-period form{display:flex;align-items:end;gap:12px;flex-wrap:wrap}.analytics-period label,.analytics-settings label{display:grid;gap:7px;font-size:12px}.analytics-period input,.analytics-settings select,.analytics-chart select{padding:10px;border:1px solid #dbe6df;border-radius:7px;max-width:100%;background:#fff}.analytics-period small{font-size:11px;color:#687d74}.analytics-settings{padding:24px;margin-bottom:24px}.analytics-settings h2{font-size:17px}.analytics-settings fieldset{border:0;padding:0;display:grid;gap:16px}.analytics-settings .analytics-check{display:flex;align-items:center;gap:10px}.analytics-settings p,.analytics-footnote{font-size:12px;line-height:1.8;color:#657b71}.analytics-settings button{justify-self:start}.analytics-notice{padding:16px;background:#fff4d5;line-height:1.7}.analytics-stats .stat-card{padding:22px;min-width:0}.analytics-stats .stat-card strong{font-size:32px}.analytics-stats .stat-card small{line-height:1.6}.analytics-stats .stat-card .analytics-money{font-size:26px;overflow-wrap:anywhere}.analytics-chart{margin-bottom:24px}.analytics-chart .panel-heading{flex-wrap:wrap;gap:15px}.analytics-plot{display:flex;gap:10px;padding:15px 25px 0}.analytics-scale{font-size:10px;color:#718278;display:flex;flex-direction:column;justify-content:space-between;padding:20px 0;min-width:28px}.analytics-plot svg{display:block;width:100%;height:230px;overflow:visible}.analytics-dates{display:flex;justify-content:space-between;padding:0 25px 20px 64px;font-size:11px;color:#718278}.analytics-zero{padding:0 25px 20px;font-size:13px;color:#687d74;line-height:1.8}.analytics-chart details{padding:18px 24px;border-top:1px solid #e3ece7}.analytics-chart summary{font-size:12px;cursor:pointer}.analytics-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;margin-bottom:24px}.analytics-grid .panel{margin:0;min-width:0}.analytics-grid .panel-heading{flex-wrap:wrap;gap:10px}.analytics-grid .panel-heading small{font-size:11px;color:#687d74}.analytics-ranking{padding:22px;display:grid;gap:22px}.analytics-ranking>div>div{display:flex;gap:12px;justify-content:space-between;align-items:start;font-size:12px;overflow-wrap:anywhere}.analytics-ranking span{min-width:0}.analytics-ranking strong{white-space:nowrap}meter{display:block;width:100%;height:12px;margin-top:8px;accent-color:#287253}.analytics-actions{margin-bottom:24px}.analytics-actions .panel-heading p{max-width:650px;line-height:1.7}.analytics-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;padding:24px}.analytics-steps>div{background:#f0f6f2;border-radius:9px;padding:20px;display:grid;gap:12px}.analytics-steps span{font-size:12px}.analytics-steps strong{font-size:30px}.analytics-steps small{font-size:11px;color:#687d74}.analytics-actions>.analytics-footnote{padding:0 24px 16px}.analytics-workspace td{overflow-wrap:anywhere}.analytics-workspace button:disabled{opacity:.5;cursor:wait}@media(max-width:1100px){.analytics-grid{grid-template-columns:1fr}.analytics-steps{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:540px){.analytics-period{align-items:stretch}.analytics-period form{width:100%}.analytics-period label{flex:1;min-width:120px}.analytics-period form button{width:100%}.analytics-steps{padding:16px;gap:10px}.analytics-steps>div{padding:14px}.analytics-steps strong{font-size:25px}.analytics-ranking{padding:16px}.analytics-scale{min-width:24px}.analytics-plot{padding-right:15px;padding-left:15px}.analytics-stats .stat-card strong{font-size:28px}}
</style>
